#!/usr/bin/env node
// Build tistu/js/vendor/memory.js: the server's own memory math for the browser (N1 Memory Time Machine).
//
// The three pure modules under tee/src/memory (records.ts → calibration.ts → rows.ts) are type-stripped with
// Node's built-in `stripTypeScriptTypes` (no npm, no network) and concatenated into one ES module, in
// dependency order, with their local imports removed. Nothing is reimplemented: the browser replays
// calibration with byte-for-byte the same code the compiler runs (tee/test/timemachine.test.ts pins it).
//
//   node tistu/js/vendor/build-memory.mjs           # writes memory.js
//   node tistu/js/vendor/build-memory.mjs --check   # exit 1 if memory.js is stale
import { stripTypeScriptTypes } from 'node:module';
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const SRC = join(here, '..', '..', '..', 'tee', 'src', 'memory');
export const MODULES = ['records.ts', 'calibration.ts', 'rows.ts'];
export const OUT = join(here, 'memory.js');

/** Bundle the modules into one ESM source string (pure; used by the build and by the drift test). */
export function bundleMemory(readFile = (p) => readFileSync(p, 'utf8')) {
  const names = new Map();
  const parts = MODULES.map((m) => {
    const ts = readFile(join(SRC, m));
    if (/\bprocess\.env\b|from 'node:/.test(ts)) throw new Error(`${m} is not browser-pure`);
    let js = stripTypeScriptTypes(ts, { mode: 'strip' });
    // local imports are satisfied by concatenation; a stripped `import type` leaves an empty specifier list
    js = js.replace(/^import\s*\{[^}]*\}\s*from\s*'\.\/(records|calibration|rows)\.ts';?[ \t]*$/gm, '');
    // the same top-level name declared twice would silently shadow: refuse
    for (const [, name] of js.matchAll(/^(?:export\s+)?(?:const|let|var|function|class)\s+([A-Za-z_$][\w$]*)/gm)) {
      if (names.has(name)) throw new Error(`duplicate top-level name ${name} in ${m} (also in ${names.get(name)})`);
      names.set(name, m);
    }
    return `// ---- tee/src/memory/${m}\n${js.replace(/[ \t]+$/gm, '').replace(/\n{3,}/g, '\n\n').trim()}\n`;
  });
  return `/* GENERATED by tistu/js/vendor/build-memory.mjs from ${MODULES.map((m) => 'tee/src/memory/' + m).join(', ')}.\n` +
    `   Do not edit: the Memory Time Machine must run the server's own calibration code. Rebuild: node tistu/js/vendor/build-memory.mjs */\n` +
    parts.join('\n');
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const out = bundleMemory();
  if (process.argv.includes('--check')) {
    let cur = '';
    try { cur = readFileSync(OUT, 'utf8'); } catch {}
    if (cur !== out) { console.error('memory.js is stale: run node tistu/js/vendor/build-memory.mjs'); process.exit(1); }
    console.log('memory.js up to date');
  } else {
    writeFileSync(OUT, out);
    console.log(`wrote ${OUT} (${out.length} bytes)`);
  }
}
